"""Regenerate the embedded gzip page after editing web/index.html."""
from pathlib import Path
import gzip

root = Path(__file__).resolve().parent.parent
page = (root / 'web' / 'index.html').read_bytes()
packed = gzip.compress(page, compresslevel=9, mtime=0)
lines = [', '.join(f'0x{b:02x}' for b in packed[i:i+16]) for i in range(0, len(packed), 16)]
(root / 'WebPage.h').write_text(
    '// Generated by scripts/pack_web.py; edit web/index.html.\n'
    '#pragma once\n#include <avr/pgmspace.h>\n'
    'const uint8_t WEB_PAGE[] PROGMEM = {\n' + ',\n'.join(lines) + '\n};\n', encoding='ascii')
print(f'Web page: {len(page)} -> {len(packed)} bytes (gzip)')
